        const warnings = Array.isArray(data.warnings) ? data.warnings : []
        const counts = data.counts ?? {}
        const chips = []
        if (Number.isFinite(counts.runningTurns) && counts.runningTurns > 0) chips.push(`运行中 ${counts.runningTurns}`)
